import{_ as e,o as t,c as o,a2 as i}from"./chunks/framework.CDpkVv68.js";const p=JSON.parse('{"title":"Panorama de Magery","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/magic/overview.md","filePath":"es/guide/magic/overview.md"}'),r={name:"es/guide/magic/overview.md"};function n(d,a,s,c,l,m){return t(),o("div",null,[...a[0]||(a[0]=[i('<h1 id="magery-overview" tabindex="-1">Panorama de Magery <a class="header-anchor" href="#magery-overview" aria-label="Enlace permanente a &quot;Panorama de Magery&quot;">​</a></h1><p><strong>Estado:</strong> Propuesto · No se ha establecido que el nuevo diseño sea jugable.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>Magery permite la ejecución; los Core Patterns aportan el conocimiento aprendido de hechizos.</li><li>Familiarity, Active Memory y las variantes compatibles determinan las opciones prácticas.</li><li>El descubrimiento continúa más allá del dominio de la habilidad; estas mecánicas siguen en estado Propuesto.</li></ul><p>Magery mide la ejecución, no el conocimiento automático de todos los hechizos. Descubrimiento, práctica y preparación dan opciones distintas a dos magos con la misma habilidad.</p><h2 id="at-a-glance" tabindex="-1">De un vistazo <a class="header-anchor" href="#at-a-glance" aria-label="Enlace permanente a &quot;De un vistazo&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capa</th><th>Qué significa</th></tr></thead><tbody><tr><td>Core Pattern</td><td>Identidad estable de un hechizo aprendido</td></tr><tr><td>Glifo / variante</td><td>Modificación compatible aprendida con contrapartidas</td></tr><tr><td>Magery</td><td>Ejecución técnica</td></tr><tr><td>Familiarity</td><td>Práctica con un patrón concreto</td></tr><tr><td>Active Memory</td><td>Conjunto limitado de opciones listas</td></tr></tbody></table><h2 id="progression-and-trade-offs" tabindex="-1">Progresión y contrapartidas <a class="header-anchor" href="#progression-and-trade-offs" aria-label="Enlace permanente a &quot;Progresión y contrapartidas&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dirección</th><th>Límite</th></tr></thead><tbody><tr><td>Aprender por el mundo</td><td>Los umbrales de habilidad por sí solos no enseñan hechizos</td></tr><tr><td>Preparar patrones conocidos</td><td>Memorizar no equivale a lanzar instantáneamente</td></tr><tr><td>Modificar hechizos</td><td>Combinaciones acotadas, no creación ilimitada de hechizos</td></tr><tr><td>Llegar a 100</td><td>Dominio técnico, no haber completado la magia</td></tr></tbody></table><p>Los patrones raros, escuelas, rituales, conocimiento regional, grimorios, reactivos e Inscription siguen siendo metas a largo plazo dentro del enfoque propuesto sin 120 ordinario. Este batch de combate no añade cifras para hechizos.</p><h2 id="example" tabindex="-1">Ejemplo <a class="header-anchor" href="#example" aria-label="Enlace permanente a &quot;Ejemplo&quot;">​</a></h2><p>Un mago puede conocer un hechizo útil pero necesitar todavía tiempo de consulta si no lo preparó para el encuentro.</p><h2 id="related" tabindex="-1">Relacionado <a class="header-anchor" href="#related" aria-label="Enlace permanente a &quot;Relacionado&quot;">​</a></h2><p><a href="/Syrolands-Public/es/guide/magic/learning-spells.html">Aprendizaje</a> · <a href="/Syrolands-Public/es/guide/magic/memory-and-familiarity.html">Memoria</a> · <a href="/Syrolands-Public/es/guide/magic/variants-and-glyphs.html">Variantes</a> · <a href="/Syrolands-Public/es/guide/magic/meditation-and-concentration.html">Meditation</a> · <a href="/Syrolands-Public/es/guide/magic/spellbooks-scrolls-and-reagents.html">Libros y reactivos</a> · <a href="/Syrolands-Public/es/guide/professions/inscription.html">Inscription</a> · <a href="/Syrolands-Public/es/game-design/magic.html">Diseño completo</a></p>',14)])])}const u=e(r,[["render",n]]);export{p as __pageData,u as default};
